schema.content:
Table "address" {
  "address_id" INTEGER [pk]
  "street_number" TEXT
  "street_name" TEXT
  "city" TEXT
  "country_id" INTEGER
}

Table "address_status" {
  "status_id" INTEGER [pk]
  "address_status" TEXT
}

Table "author" {
  "author_id" INTEGER [pk]
  "author_name" TEXT
}

Table "book" {
  "book_id" INTEGER [pk]
  "title" TEXT
  "isbn13" TEXT
  "language_id" INTEGER
  "num_pages" INTEGER
  "publication_date" DATE
  "publisher_id" INTEGER
}

Table "book_author" {
  "book_id" INTEGER [pk]
  "author_id" INTEGER [pk]
}

Table "book_language" {
  "language_id" INTEGER [pk]
  "language_code" TEXT
  "language_name" TEXT
}

Table "country" {
  "country_id" INTEGER [pk]
  "country_name" TEXT
}

Table "cust_order" {
  "order_id" INTEGER [pk]
  "order_date" TIMESTAMP
  "customer_id" INTEGER
  "shipping_method_id" INTEGER
  "dest_address_id" INTEGER
}

Table "customer" {
  "customer_id" INTEGER [pk]
  "first_name" TEXT
  "last_name" TEXT
  "email" TEXT
}

Table "customer_address" {
  "customer_id" INTEGER [pk]
  "address_id" INTEGER [pk]
  "status_id" INTEGER
}

Table "order_history" {
  "history_id" INTEGER [pk]
  "order_id" INTEGER
  "status_id" INTEGER
  "status_date" TIMESTAMP
}

Table "order_line" {
  "line_id" INTEGER [pk]
  "order_id" INTEGER
  "book_id" INTEGER
  "price" REAL
}

Table "order_status" {
  "status_id" INTEGER [pk]
  "status_value" TEXT
}

Table "publisher" {
  "publisher_id" INTEGER [pk]
  "publisher_name" TEXT
}

Table "shipping_method" {
  "method_id" INTEGER [pk]
  "method_name" TEXT
  "cost" REAL
}



Ref: "address"."country_id" > "country"."country_id"

Ref: "customer_address"."customer_id" > "customer"."customer_id"

Ref: "customer_address"."address_id" > "address"."address_id"

Ref: "book"."publisher_id" > "publisher"."publisher_id"

Ref: "book"."language_id" > "book_language"."language_id"

Ref: "book_author"."book_id" > "book"."book_id"

Ref: "book_author"."author_id" > "author"."author_id"
